import { mountUIPagesSkin } from './ui-pages-skin.js';
import { mountReadiness, mountReadinessComponent } from './ui-readiness.js';
import { mountLogistics } from './ui-logistics.js';
import { PAGE_IDS, COMPONENTS, loadPagesState, savePagesState } from './ui-pages-state.js';
import { loadBenchState } from './bench-store.js?v=grid-1';
import { PIXEL_PITCH, UI_CELL, UI_PIXELS, floorCell } from './viewer-grid.js?v=pane-140';

const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state=loadPagesState();let skin,disposePage=()=>{},disposePreview=()=>{},tourStep=-1;
const PAGES={catalog:['COMPONENT ATLAS','DESIGN SYSTEM / REFERENCE COMPONENTS','SELECT / TEST / ANNOTATE / ASSEMBLE'],home:['READINESS','MISSION / WELCOME','NEWS / UPDATES / RESOURCES'],cases:['CASE WORKSPACE','READINESS / MAINTENANCE','PREDICT / PLAN / EXECUTE'],parts:['SPARE PARTS','READINESS / INVENTORY','SEARCH / INSPECT / FORECAST'],value:['VALUE DASHBOARD','READINESS / IMPACT','REALIZED / POTENTIAL'],logistics:['LOGISTICS','OPERATIONS / COMMON PICTURE','INSIGHTS / MAP / ALERTS']};
function refresh(){skin?.refresh();}
function persist(){const ok=savePagesState(state);if(!ok)notify('STORAGE UNAVAILABLE / CHANGES KEPT THIS SESSION');return ok;}
function notify(message){$('lab-message').textContent=String(message).toUpperCase();refresh();}
const options={refresh:()=>{snapTracks();skin?.relayout();},navigate,notify};
function snapTracks(){for(const el of document.querySelectorAll('.grid-2,.grid-3,.metrics')){el.style.removeProperty('grid-template-columns');if(innerWidth<=760)continue;const s=getComputedStyle(el);if(s.display!=='grid')continue;const count=el.classList.contains('grid-2')?2:3;const available=el.getBoundingClientRect().width-parseFloat(s.paddingLeft)-parseFloat(s.paddingRight)-(parseFloat(s.columnGap)||0)*(count-1);if(available<=0)continue;const first=floorCell(available/count);const last=Math.max(UI_CELL,floorCell(available-first*(count-1)));el.style.gridTemplateColumns=[...Array(count-1).fill(`${first}px`),`${last}px`].join(' ');}}
function layout(){document.documentElement.style.setProperty('--surface-width',`${floorCell(innerWidth)}px`);document.documentElement.style.setProperty('--pixel',`${PIXEL_PITCH}px`);document.documentElement.style.setProperty('--cell',`${UI_CELL}px`);document.body.dataset.pixelPitch=PIXEL_PITCH;document.body.dataset.uiPixels=UI_PIXELS;snapTracks();skin?.relayout();}
layout();window.addEventListener('resize',layout);
$('page-nav').innerHTML=Object.entries(PAGES).map(([id,[label]])=>`<button type="button" data-page="${id}" data-vfd="button">${id==='catalog'?'COMPONENT ATLAS':label}</button>`).join('');
$('page-nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page);});
function navigate(page,{history=true}={}){if(!PAGE_IDS.includes(page))page='catalog';disposePreview();disposePreview=()=>{};disposePage();disposePage=()=>{};state.page=page;persist();const [title,kicker,summary]=PAGES[page];$('page-title').textContent=title;$('page-kicker').textContent=kicker;$('page-summary').textContent=summary;document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.page===page)));$('page-host').replaceChildren();if(page==='catalog')mountCatalog();else if(page==='logistics')disposePage=mountLogistics($('page-host'),options)||(()=>{});else disposePage=mountReadiness($('page-host'),page,options)||(()=>{});if(history){const url=new URL(location.href);url.searchParams.set('page',page);window.history.replaceState(null,'',url);}document.body.dataset.page=page;window.scrollTo({top:0,left:0,behavior:'instant'});notify('READY / '+title+' / DEMO DATA');skin?.relayout();}
function mountCatalog(){const host=$('page-host');host.innerHTML=`<div class="catalog-layout"><section class="panel catalog-list stack" data-vfd="panel"><span class="eyebrow" data-vfd="label">COMPONENT INDEX / ${COMPONENTS.length}</span><input id="component-search" type="search" data-vfd="search" placeholder="FIND A COMPONENT" aria-label="Search components"><div id="catalog-items" class="catalog-items"></div></section><div class="catalog-detail"><section class="panel catalog-intro" data-vfd="panel"><div><span id="component-family" class="eyebrow" data-vfd="label"></span><h2 id="component-name" data-vfd="label" data-vfd-scale="2"></h2><p id="component-description" data-vfd="label"></p></div><div class="catalog-meta"><span id="component-source" data-vfd="label" class="muted"></span><button id="assemble-page" data-vfd="button">OPEN PAGE</button></div></section><section class="panel" data-vfd="panel"><div class="panel-head"><h3 data-vfd="label">LIVE COMPONENT</h3><span data-vfd="label" data-vfd-tone="dim">INTERACTIVE / SAME PAGE SOURCE</span></div><div id="component-preview" class="catalog-preview"></div></section><section class="panel note-panel" data-vfd="panel"><label><span data-vfd="label">EDIT NOTE / THIS COMPONENT</span><textarea id="component-note" data-vfd="search" maxlength="4000" aria-label="Component edit note" placeholder="DESCRIBE AN EDIT TO KEEP WITH THIS COMPONENT"></textarea></label><aside><h3 id="note-status" data-vfd="label">SAVED ON THIS DEVICE</h3><p data-vfd="label" class="muted">NOTES STAY WITH EACH COMPONENT WHILE YOU EXPLORE THE PAGES.</p><button id="save-component-note" data-vfd="button">SAVE NOTE</button><button id="export-ui-notes" data-vfd="button">EXPORT NOTES</button></aside></section></div></div>`;
  const list=()=>{const query=$('component-search').value.toLowerCase();$('catalog-items').innerHTML=COMPONENTS.filter(c=>(c.name+' '+c.family+' '+c.reference).toLowerCase().includes(query)).map(c=>`<button data-component="${c.id}" data-vfd="button" aria-pressed="${state.selected===c.id}">${esc(c.name)}</button>`).join('')||'<p data-vfd="label" class="empty">NO MATCHING COMPONENTS</p>';refresh();};
  $('component-search').addEventListener('input',list);$('catalog-items').addEventListener('click',e=>{const b=e.target.closest('[data-component]');if(b){state.selected=b.dataset.component;persist();list();selectComponent();}});
  $('assemble-page').addEventListener('click',()=>navigate(COMPONENTS.find(c=>c.id===state.selected).page));
  $('component-note').addEventListener('input',()=>{state.notes[state.selected]=$('component-note').value;$('note-status').textContent=persist()?'NOTE SAVED':'SESSION ONLY';refresh();});
  $('save-component-note').addEventListener('click',()=>{state.notes[state.selected]=$('component-note').value;if(persist()){$('note-status').textContent='NOTE SAVED';notify('EDIT NOTE SAVED / '+state.selected);}refresh();});
  $('export-ui-notes').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'phosphor-ui-notes',version:1,components:COMPONENTS.map(c=>({id:c.id,name:c.name,page:c.page,note:state.notes[c.id]||''}))},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='phosphor-ui-notes.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('COMPONENT NOTES EXPORTED');});list();selectComponent();
}
function selectComponent(){disposePreview();const item=COMPONENTS.find(c=>c.id===state.selected);$('component-family').textContent=item.family+' / REUSABLE COMPONENT';$('component-name').textContent=item.name.toUpperCase();$('component-description').textContent=item.description.toUpperCase();$('component-source').textContent='FOUND IN / '+item.reference;$('component-note').value=state.notes[item.id]||'';$('note-status').textContent=state.notes[item.id]?'NOTE SAVED':'READY FOR EDIT NOTES';const host=$('component-preview');host.replaceChildren();if(item.page!=='logistics')disposePreview=mountReadinessComponent(host,item.id,options)||(()=>{});else {const clean=mountLogistics(host,options)||(()=>{});let pending=0;const scope=()=>{pending=0;scopeComponent(host,item.id);skin?.relayout();};const observer=new MutationObserver(()=>{if(!pending)pending=requestAnimationFrame(scope);});observer.observe(host,{childList:true,subtree:true});scope();disposePreview=()=>{cancelAnimationFrame(pending);observer.disconnect();clean();};}skin?.relayout();}
function scopeComponent(host,id){
  const primary=['map-toolbar','map-legend'].includes(id)?'map':id;
  const ids=primary==='command-search'?['command-search','map','alerts']:['insights','map'].includes(primary)?[primary,'alerts']:[primary];
  const targets=ids.map(key=>host.querySelector(`[data-ui-component="${key}"]`)).filter(Boolean);if(!targets.length)return;
  host.querySelectorAll('[data-catalog-hidden]').forEach(e=>e.removeAttribute('data-catalog-hidden'));
  host.querySelectorAll('.catalog-path,.catalog-target').forEach(e=>e.classList.remove('catalog-path','catalog-target'));
  const paths=new Set();for(const target of targets)for(let node=target;node&&node!==host;node=node.parentElement)paths.add(node);
  for(const target of targets){target.classList.add('catalog-target');for(let node=target;node&&node!==host;node=node.parentElement){for(const sibling of node.parentElement.children)if(!paths.has(sibling))sibling.setAttribute('data-catalog-hidden','');if(!targets.includes(node))node.classList.add('catalog-path');}}
}
let baseOptics={brightness:100,glow:25,contrast:110,grid:35,refraction:0};try{baseOptics=loadBenchState().state.optics;}catch{}
state.optics={...baseOptics,...state.optics};
const opticalFields=[['brightness','EMISSION',20,200],['glow','BLOOM',0,100],['contrast','CONTRAST',50,220],['grid','CELL MASK',0,100],['refraction','REFRACTION',0,100]];
$('optics-fields').innerHTML=opticalFields.map(([key,label,min,max])=>`<label class="field"><span data-vfd="label" id="optics-${key}-label">${label} / ${state.optics[key]}%</span><input type="range" data-vfd="slider" data-optics="${key}" min="${min}" max="${max}" value="${state.optics[key]}" aria-label="${label}"></label>`).join('');
$('optics-fields').addEventListener('input',e=>{const key=e.target.dataset.optics;if(!key)return;state.optics[key]=Number(e.target.value);$('optics-'+key+'-label').textContent=opticalFields.find(a=>a[0]===key)[1]+' / '+e.target.value+'%';skin?.setOptics?.(state.optics);persist();refresh();});
$('page-pattern').value=state.mark;$('page-pattern').addEventListener('change',e=>{state.mark=e.target.value;persist();refresh();});
function display(open){$('display-drawer').hidden=!open;$('open-optics').setAttribute('aria-expanded',String(open));skin?.relayout();if(open)$('close-optics').focus();else $('open-optics').focus();}
$('open-optics').addEventListener('click',()=>display($('display-drawer').hidden));$('close-optics').addEventListener('click',()=>display(false));
$('reset-optics').addEventListener('click',()=>{state.optics={...baseOptics};for(const [key,label] of opticalFields){document.querySelector(`[data-optics="${key}"]`).value=state.optics[key];$('optics-'+key+'-label').textContent=label+' / '+state.optics[key]+'%';}skin?.setOptics?.(state.optics);persist();refresh();});
$('grid-toggle').setAttribute('aria-pressed',String(state.guides));$('grid-toggle').addEventListener('click',()=>{state.guides=!state.guides;$('grid-toggle').setAttribute('aria-pressed',String(state.guides));persist();refresh();});
const TOUR=[['home','WELCOME / READINESS','THE REFERENCE WELCOME PAGE BECOMES A MISSION BANNER, NEWS CARDS, UPDATES AND RESOURCE LIST.'],['cases','MAINTENANCE WORKFLOW','THE STATUS STEPPER TRACKS A CASE FROM OPEN THROUGH RECOMMENDATION, SCHEDULING, VERIFICATION AND CLOSURE.'],['cases','TAKE ACTION','USE THE QUICK ACTION GUIDE TO ADVANCE THE DEMO CASE. TABS KEEP ALERTS, PARTS AND MAINTENANCE TOGETHER.'],['parts','SPARE PART DEMAND','FILTER AND SEARCH THE INVENTORY TABLE. SELECT A STOCK NUMBER TO LINK ITS ROW TO THE FORECAST.'],['parts','INVENTORY FORECAST','COMPARE ACTUAL AND FORECAST INVENTORY AGAINST THE REORDER LINE. TOGGLE SERIES AND ADJUST THE DATE RANGE.'],['value','APPLICATION VALUE','SWITCH BETWEEN VALUE AND HOURS. FILTER THE DEMO PLATFORMS TO UPDATE THE SUMMARY AND COMPARISON.'],['logistics','LOGISTICS PICTURE','PAN THE MAP, SELECT A PORT, FILTER ALERTS AND TOGGLE LAYERS. THE COMMAND BAR SEARCHES LOCAL DEMO RECORDS.'],['catalog','COMPONENT ATLAS','EACH BUILDING BLOCK HAS A LIVE EXAMPLE AND ITS OWN SAVED EDIT NOTE. OPEN ITS ASSEMBLED PAGE TO TEST THE FULL FLOW.']];
function showTour(index){tourStep=Math.max(0,Math.min(TOUR.length-1,index));const [page,title,copy]=TOUR[tourStep];navigate(page);$('tour-count').textContent=`GUIDED TOUR / ${tourStep+1} OF ${TOUR.length}`;$('tour-title').textContent=title;$('tour-copy').textContent=copy;$('tour-back').disabled=tourStep===0;$('tour-next').textContent=tourStep===TOUR.length-1?'FINISH':'NEXT';$('tour').hidden=false;skin?.relayout();}
function closeTour(){tourStep=-1;$('tour').hidden=true;skin?.relayout();$('start-tour').focus();}
$('start-tour').addEventListener('click',()=>showTour(0));$('tour-back').addEventListener('click',()=>showTour(tourStep-1));$('tour-next').addEventListener('click',()=>tourStep===TOUR.length-1?closeTour():showTour(tourStep+1));$('tour-close').addEventListener('click',closeTour);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('tour').hidden)closeTour();if(!$('display-drawer').hidden)display(false);}});
const requested=new URL(location.href).searchParams.get('page');navigate(PAGE_IDS.includes(requested)?requested:state.page);
skin=mountUIPagesSkin({getState:()=>state});skin.setOptics?.(state.optics);skin.relayout();
window.addEventListener('pagehide',event=>{if(event.persisted)return;disposePreview();disposePage();skin.destroy();window.removeEventListener('resize',layout);});
window.addEventListener('pageshow',event=>{if(event.persisted){layout();refresh();}});
